#!/usr/bin/env bash
# Build a separate working tree for the release from the research data folder,
# so the release pipeline never overwrites the research outputs.
#   - small source files are copied
#   - large arrays and SEG-Y are hard-linked (no extra disk use; the pipeline
#     unlinks before saving, so the originals are never modified in place)
#   - the well CSVs are NOT carried over: they are regenerated by the pipeline
#
# Usage: release/make_worktree.sh <research data/volve> <worktree>
set -euo pipefail
SRC=$(realpath "$1"); DST=$(realpath -m "$2")
mkdir -p "$DST/prepared" "$DST/seismic"
for d in welllogs trajectories checkshots markers; do cp -r "$SRC/$d" "$DST/"; done
mkdir -p "$DST/dbx_extract"; cp -r "$SRC/dbx_extract/surveys" "$SRC/dbx_extract/w19" "$DST/dbx_extract/"
cp "$SRC/seismic/SeismicOrderSummary+Header.txt" "$DST/seismic/"
for f in cubo_st0202_depth.npy vel_st10010_depth.npy vel_coreg_st0202.npy \
         pp_poststack_time.npy pp_coreg_st0202.npy; do
  ln -f "$SRC/prepared/$f" "$DST/prepared/$f"
done
for f in cubo_st0202_geom.json vel_st10010_geom.json pp_geom_time.json; do
  cp "$SRC/prepared/$f" "$DST/prepared/"
done
echo "worktree ready: $DST"
echo "next: VOLVE_DATA=$DST python pipeline/parse_compass_survey.py && VOLVE_DATA=$DST python pipeline/amarre_volve.py"
